/* Page documents retain legacy elements as the initial page, with explicit prototype targets. */
function ensurePages(){if(!current.pages){checkpoint();current.pages=[{id:uid(),name:'首页',elements:current.elements,scrollHeight:800}];current.startPage=current.pages[0].id}return current.pages}
let designPageId=null;
function activeDesignPage(){const pages=ensurePages();return pages.find(p=>p.id===designPageId)||pages[0]}
function switchDesignPage(id){const pages=ensurePages(),old=pages.find(p=>p.id===designPageId)||pages[0];old.elements=current.elements;designPageId=id;current.editingPageId=id;current.elements=pages.find(p=>p.id===id).elements;selected=null;renderEditor()}
function addDesignPage(){const pages=ensurePages();checkpoint();const p={id:uid(),name:'页面 '+(pages.length+1),elements:baseElements('新页面','编辑内容并配置跳转'),scrollHeight:800};pages.push(p);switchDesignPage(p.id)}
function pageSettings(){const p=activeDesignPage();modal('页面设置',`<label>页面名称<input id="pageName" value="${esc(p.name)}"></label><label>纵向内容高度（大于 800 即可滚动）<input type="number" id="pageHeight" min="800" max="8000" value="${p.scrollHeight||800}"></label><label class="checkrow"><input type="checkbox" id="pageHome" ${current.startPage===p.id?'checked':''}>作为原型首页</label>`,`<button id="savePage" class="primary">保存</button>`);$('#savePage').onclick=()=>{checkpoint();p.name=$('#pageName').value;p.scrollHeight=Math.max(800,Math.min(8000,+$('#pageHeight').value));if($('#pageHome').checked)current.startPage=p.id;closeModal();renderEditor()}}
const protoLeft=renderLeft;renderLeft=function(){if(view==='prototype'){$('#leftpanel').innerHTML='<h3>原型页面</h3>'+ensurePages().map(p=>'<p>'+esc(p.name)+'</p>').join('')+'<p>点击画面元素进行跳转；长页面在画面内部滚动。</p>';return}protoLeft();if(view!=='design')return;const pages=ensurePages();if(!designPageId||!pages.some(p=>p.id===designPageId))designPageId=pages[0].id;current.editingPageId=designPageId;const p=activeDesignPage();p.elements=current.elements;$('#leftpanel').insertAdjacentHTML('afterbegin',`<h3>页面 / 原型</h3>${pages.map(p=>`<button style="display:block;width:100%;margin:6px 0" class="${p.id===designPageId?'soft':''}" onclick="switchDesignPage('${p.id}')">${esc(p.name)} ${p.id===current.startPage?'⌂':''}</button>`).join('')}<button onclick="addDesignPage()">＋ 页面</button><button onclick="pageSettings()">页面设置</button><button onclick="duplicateDesignPage()">复制页面</button><button onclick="previewPrototype()">▶ 播放原型</button><hr>`)};
const protoRight=renderRight;renderRight=function(){if(view==='prototype'){$('#rightpanel').innerHTML='<h3>原型播放</h3><p>入口由页面设置中的首页决定。点击绑定的元素进入目标页，返回动作沿导航历史回退。</p><button onclick="view=\'design\';renderEditor()">返回界面设计</button>';return}protoRight();if(view!=='design')return;const e=current.elements.find(e=>e.id===selected);if(!e)return;$('#rightpanel').insertAdjacentHTML('beforeend',`<h3 style="margin-top:22px">原型交互</h3><label>点击跳转<select id="prototypeTarget" aria-label="点击跳转"><option value="">无页面跳转</option><option value="back" ${e.targetPage==='back'?'selected':''}>返回上一页</option>${ensurePages().map(p=>`<option value="${p.id}" ${e.targetPage===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>组件类型<select id="prototypeType" aria-label="组件类型">${['text','card','button','rectangle','icon','image','chart','component'].map(t=>`<option value="${t}" ${e.type===t?'selected':''}>${{text:'文本',card:'卡片',button:'按钮',rectangle:'矩形',icon:'图标',image:'图片',chart:'趋势图',component:'代码角色'}[t]}</option>`).join('')}</select></label>`);$('#prototypeTarget').onchange=function(){checkpoint();e.targetPage=this.value;activeDesignPage().elements=current.elements};$('#prototypeType').onchange=function(){updateElement('type',this.value);activeDesignPage().elements=current.elements};labelControls($('#rightpanel'))};
function previewPrototype(){ensurePages();activeDesignPage().elements=current.elements;const s=runtimeSession();s.prototypePage=current.startPage;s.prototypeStack=[];s.status='ready';view='prototype';renderEditor()}
const protoStage=renderStage;renderStage=function(){if(view!=='prototype'){protoStage();return}const s=runtimeSession(),p=ensurePages().find(p=>p.id===s.prototypePage)||current.pages[0];$('#stagecontent').innerHTML=`<div style="padding:24px"><h2>交互原型 · ${esc(p.name)}</h2><button onclick="view='design';renderEditor()">返回编辑</button><div class="sv-viewport" style="margin:20px auto"><div style="width:600px;height:800px;zoom:.5;overflow:auto;background:#131b23"><div style="position:relative;height:${p.scrollHeight||800}px">${p.elements.map(e=>`<div data-proto="${e.id}" tabindex="${e.targetPage?0:-1}" role="${e.targetPage?'button':'group'}" style="position:absolute;box-sizing:border-box;white-space:pre-wrap;overflow:hidden;left:${+e.x}px;top:${+e.y}px;width:${+e.w}px;height:${+e.h}px;font-size:${+e.fontSize}px;color:${safeColor(e.color,'white')};background:${safeColor(e.background,'transparent')};border-radius:${+e.radius||0}px;padding:${e.type==='card'?24:0}px;cursor:${e.targetPage?'pointer':'default'}">${esc(e.text)}</div>`).join('')}</div></div></div></div>`;$$('[data-proto]').forEach(b=>{const activate=()=>{const e=p.elements.find(e=>e.id===b.dataset.proto);if(!e.targetPage)return;if(e.targetPage==='back')s.prototypePage=s.prototypeStack.pop()||current.startPage;else{s.prototypeStack.push(p.id);s.prototypePage=e.targetPage}renderStage()};b.onclick=activate;b.onkeydown=e=>{if(e.key==='Enter')activate()}})};

const protoSave=saveCurrent;saveCurrent=async function(quiet=false){if(current?.pages&&view==='design')activeDesignPage().elements=current.elements;return protoSave(quiet)};
const protoOpen=openService;openService=function(id){designPageId=null;protoOpen(id)};

function duplicateDesignPage(){const p=activeDesignPage();checkpoint();const copied={...structuredClone(p),id:uid(),name:p.name+' 副本',elements:p.elements.map(e=>({...e,id:uid()}))};current.pages.push(copied);switchDesignPage(copied.id)}
const prototypeRenderStage=renderStage;renderStage=function(){if(view!=='prototype')return prototypeRenderStage();const s=runtimeSession();s.proto=s.proto||{page:current.startPage,stack:[]};const p=PrototypeRuntime.page(current,s.proto);$('#stagecontent').innerHTML=`<div style="padding:24px"><h2>交互原型 · ${esc(p.name)}</h2><button onclick="view='design';renderEditor()">返回编辑</button><button onclick="exportPrototype()">导出多页面原型</button>${PrototypeRuntime.render(current,s.proto)}</div>`;$$('[data-proto]').forEach(b=>{const activate=()=>{try{if(PrototypeRuntime.activate(current,s.proto,b.dataset.proto))renderStage()}catch(e){toast(e.message)}};b.onclick=activate;b.onkeydown=e=>{if(e.key==='Enter')activate()}})};
const startPrototype=previewPrototype;previewPrototype=function(){const s=runtimeSession();s.proto={page:current.startPage||ensurePages()[0].id,stack:[]};startPrototype()};
async function exportPrototype(){const source=(await Promise.all(['graphics.js','prototype-engine.js'].map(f=>fetch(f).then(r=>r.text())))).join('\n');const data=JSON.stringify({pages:current.pages,startPage:current.startPage}).replace(/</g,'\\u003c');download(current.name+'-多页面原型.html',`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>${esc(current.name)} 交互原型</title><style>body{font:14px system-ui;background:#f3f1eb;text-align:center}.sv-viewport{width:300px;height:400px;overflow:hidden} [role=button]:focus{outline:4px solid #dd3c30}</style><body><h2>${esc(current.name)} · 交互原型</h2><p>点击元素跳转，画面内部纵向滚动；所有页面均来自导出快照。</p><main></main><script>${source}\nconst doc=${data},state={page:doc.startPage,stack:[]};function draw(){document.querySelector('main').innerHTML=PrototypeRuntime.render(doc,state)}document.onclick=e=>{const b=e.target.closest('[data-proto]');if(b&&PrototypeRuntime.activate(doc,state,b.dataset.proto))draw()};document.onkeydown=e=>{if(e.key==='Enter')document.activeElement.click()};draw()<\/script></body></html>`,'text/html')}
